        const CARD_PRINT_HEIGHT_MM = 88
        const CARD_PRINT_WIDTH_PX = Math.round((CARD_PRINT_WIDTH_MM / MM_PER_INCH) * PRINT_DPI)
        const CARD_PRINT_HEIGHT_PX = Math.round((CARD_PRINT_HEIGHT_MM / MM_PER_INCH) * PRINT_DPI)

