                const scale = Math.min(CARD_PRINT_WIDTH_PX / sourceWidth, CARD_PRINT_HEIGHT_PX / sourceHeight)
                const drawWidth = Math.round(sourceWidth * scale)
                const drawHeight = Math.round(sourceHeight * scale)
                const offsetX = Math.floor((CARD_PRINT_WIDTH_PX - drawWidth) / 2)
                const offsetY = Math.floor((CARD_PRINT_HEIGHT_PX - drawHeight) / 2)

